import os, json, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_name = os.path.basename(d)
    print(f"Session dir: {d}")
    print(f"Sessions file: {d}/../../sessions/{session_name}.jsonl")

    try:
        with open(d + '/../../sessions/' + session_name + '.jsonl') as f:
            content = f.read()
    except Exception as e:
        print(f"Error reading sessions file: {e}")
        return {}, {}

    G = {}  # key -> grid

    # Extract all demo pairs and test inputs
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=\n(Demo pair \d+|Test input)|$)'
    matches = re.finditer(pattern, content, re.DOTALL)

    for m in matches:
        key = m.group(1)
        h, w = int(m.group(2)), int(m.group(3))
        rows_raw = m.group(4).strip().split('\n')

        # Parse each row
        rows = []
        for r in rows_raw[:h]:
            parts = r.split()
            if parts and parts[0].isdigit():
                rows.append([int(x) for x in parts])
            else:
                rows.append([])

        # Remove empty last rows
        while rows and all(len(r) == 0 for r in rows[-3:]):
            rows.pop()

        if len(rows) > 0 and len(rows[0]) > 0:
            G[key] = rows

    return G

G = load_grids()
